const source = $('Execute Workflow Trigger').item.json || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function extractFileName(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'thong tin file',
    'chi tiet file',
    'file info',
    'metadata file',
    'info file',
    'xem thong tin file',
    'xem chi tiet file',
    'noi dung file',
    'doc file',
    'read file'
  ];

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      return cleanName(original.slice(prefix.length + 1));
    }

    if (normalized === prefix) {
      return '';
    }
  }

  return '';
}

const fileId =
  source.fileId ||
  source.targetId ||
  payload.fileId ||
  payload.targetId ||
  '';

const fileName = cleanName(
  source.fileName ||
  source.targetName ||
  payload.fileName ||
  payload.targetName ||
  extractFileName(raw)
);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),
    fileId,
    targetId: fileId,
    fileName,
    targetName: fileName,
    hasTarget: Boolean(fileId || fileName),
    response: fileId || fileName
      ? ''
      : '📄 <b>Thông tin file</b>\n\nVí dụ: <code>thông tin file báo cáo.pdf</code>\n<code>nội dung file note.md</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      found: false,
      fileId: '',
      targetId: '',
      response: 'Không tìm thấy file phù hợp với: <i>' + escapeHtml(source.fileName || source.targetName || '') + '</i>'
    }
  }];
}

const file = rows[0];

return [{
  json: {
    ...source,
    ...file,
    found: true,
    fileId: file.id || source.fileId || '',
    targetId: file.id || source.targetId || source.fileId || '',
    fileName: file.name || source.fileName || source.targetName || '',
    targetName: file.name || source.targetName || source.fileName || '',
    webViewLink: file.webViewLink || source.webViewLink || '',
    webContentLink: file.webContentLink || source.webContentLink || '',
    mimeType: file.mimeType || source.mimeType || ''
  }
}];

const prepared = $('Prepare Action').item.json || {};
const meta = $input.item.json || {};

const fileId = meta.id || prepared.fileId || prepared.targetId || '';
const mimeType = meta.mimeType || prepared.mimeType || '';

function isTextLike(mime) {
  if (!mime) return false;
  if (mime.startsWith('text/')) return true;
  return [
    'application/json',
    'application/xml',
    'application/javascript',
    'application/typescript',
    'application/sql',
    'application/x-yaml',
    'application/toml',
    'application/x-ndjson',
    'image/svg+xml'
  ].includes(mime);
}

function workspaceExportMime(mime) {
  const map = {
    'application/vnd.google-apps.document': 'text/plain',
    'application/vnd.google-apps.spreadsheet': 'text/csv',
    'application/vnd.google-apps.presentation': 'text/plain',
    'application/vnd.google-apps.drawing': 'image/svg+xml'
  };
  return map[mime] || '';
}

let contentUrl = '';
let contentMode = '';
let canReadContent = false;
let reason = '';

const exportMime = workspaceExportMime(mimeType);

if (!fileId) {
  reason = 'Không có fileId để lấy nội dung.';
} else if (exportMime) {
  contentUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}/export?mimeType=${encodeURIComponent(exportMime)}`;
  contentMode = 'export';
  canReadContent = true;
} else if (isTextLike(mimeType)) {
  contentUrl = `https://www.googleapis.com/drive/v3/files/${encodeURIComponent(fileId)}?alt=media`;
  contentMode = 'media';
  canReadContent = true;
} else {
  reason = 'File này không phải text/code/data hoặc Google Docs export được, nên chỉ hiển thị metadata.';
}

return [{
  json: {
    ...prepared,
    ...meta,
    fileId,
    targetId: fileId,
    fileName: meta.name || prepared.fileName || prepared.targetName || '',
    mimeType,
    contentUrl,
    contentMode,
    canReadContent,
    contentReason: reason
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });
};

const formatSize = (bytes) => {
  const n = Number(bytes);
  if (!Number.isFinite(n) || n < 0) return '';
  if (n < 1024) return `${n} B`;
  if (n < 1024 ** 2) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 ** 3) return `${(n / 1024 ** 2).toFixed(1)} MB`;
  return `${(n / 1024 ** 3).toFixed(1)} GB`;
};

const getFileType = (mimeType = '') => {
  if (mimeType === 'application/vnd.google-apps.folder') return 'Folder';
  if (mimeType === 'application/vnd.google-apps.document') return 'Google Docs';
  if (mimeType === 'application/vnd.google-apps.spreadsheet') return 'Google Sheets';
  if (mimeType === 'application/vnd.google-apps.presentation') return 'Google Slides';
  if (mimeType === 'application/pdf') return 'PDF';
  if (mimeType.includes('wordprocessingml') || mimeType === 'application/msword') return 'Word';
  if (mimeType.includes('spreadsheetml') || mimeType === 'application/vnd.ms-excel') return 'Excel';
  if (mimeType.includes('presentationml') || mimeType === 'application/vnd.ms-powerpoint') return 'PowerPoint';
  if (mimeType.startsWith('image/')) return 'Image';
  if (mimeType.startsWith('video/')) return 'Video';
  if (mimeType.startsWith('audio/')) return 'Audio';
  if (mimeType.startsWith('text/')) return 'Text';
  if (mimeType.includes('zip') || mimeType.includes('compressed')) return 'Archive';
  return mimeType || 'Không rõ';
};

const meta = $('Prepare Content Request').item.json || {};
const contentResult = $input.item.json;

let content = '';

if (typeof contentResult === 'string') {
  content = contentResult;
} else if (contentResult && typeof contentResult === 'object') {
  if (typeof contentResult.data === 'string') content = contentResult.data;
  else if (typeof contentResult.body === 'string') content = contentResult.body;
  else if (typeof contentResult.response === 'string') content = contentResult.response;
  else if (typeof contentResult.content === 'string') content = contentResult.content;
  else content = JSON.stringify(contentResult, null, 2);
} else if (contentResult !== undefined && contentResult !== null) {
  content = String(contentResult);
}

const name = meta.name || meta.fileName || meta.targetName || 'Không rõ tên';
const fileId = meta.id || meta.fileId || meta.targetId || '';
const mimeType = meta.mimeType || '';
const fileType = getFileType(mimeType);
const created = formatDate(meta.createdTime);
const modified = formatDate(meta.modifiedTime);
const size = formatSize(meta.size);
const link = meta.webViewLink || meta.webContentLink || (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

let text = '📄 <b>Thông tin file</b>\n\n';
text += `<b>${escapeHtml(name)}</b>\n`;
if (fileId) text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
text += `Loại: ${escapeHtml(fileType)}\n`;
if (mimeType) text += `MIME: <code>${escapeHtml(mimeType)}</code>\n`;
if (created) text += `Tạo lúc: ${escapeHtml(created)}\n`;
if (modified) text += `Sửa lúc: ${escapeHtml(modified)}\n`;
if (size) text += `Kích thước: ${escapeHtml(size)}\n`;

if (Array.isArray(meta.owners) && meta.owners.length) {
  const owners = meta.owners
    .map((owner) => pickFirst(owner.displayName, owner.emailAddress))
    .filter(Boolean)
    .join(', ');
  if (owners) text += `Chủ sở hữu: ${escapeHtml(owners)}\n`;
}

if (link) text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>\n`;

const preview = String(content || '').slice(0, 1800);
if (preview) {
  text += `\n<b>Nội dung xem trước:</b>\n<pre>${escapeHtml(preview)}</pre>`;
  if (String(content).length > 1800) text += '\n<i>Nội dung đã được rút gọn vì quá dài.</i>';
} else {
  text += '\n<i>Không đọc được nội dung hoặc file rỗng.</i>';
}

return [{ json: { chatId: meta.chatId, text: text.trim() } }];

